using Rory.Data;
using UnityEngine;

namespace Rory.Popups.Game
{
    /// <summary>
    /// Prefabs of the in-game windows (match-3, hidden object, dessert, kitchen), generated by
    /// GameWindowsBuilder and loaded from Resources/GameWindows. Use <see cref="GameWindows"/> to open them.
    /// </summary>
    [CreateAssetMenu(menuName = "Rory/Game Windows Library")]
    public class GameWindowsLibrary : ScriptableObject
    {
        [Tooltip("PAUSE_GAME: big window with sound / music / full screen toggles")]
        public PausePopup pause;
        [Tooltip("CONFIRM_MAINMENU / CONFIRM_KITCHEN: small yes/no window")]
        public WindowPopup confirm;
        [Tooltip("SHOW_EXPERT_NEEDED_INFO: small window with a text-only OK")]
        public WindowPopup info;
        [Tooltip("Level summaries (STORY_*, HO_*, DESSERT_*)")]
        public ResultPopup result;
        [Tooltip("LevelEvent.xml window, size=\"big\"")]
        public DayEventPopup eventBig;
        [Tooltip("LevelEvent.xml window, size=\"small\"")]
        public DayEventPopup eventSmall;
        [Tooltip("Goal / expert badge that pops in the HUD when the goal is reached (showGoalIconSmall)")]
        public GoalIconSmall goalIconSmall;

        [Header("Shared art")]
        public Sprite buttonOn;
        public Sprite buttonOff;
        public Sprite goal;
        public Sprite expert;
        public ParticleConfig congrats;

        static GameWindowsLibrary instance;

        public static GameWindowsLibrary Instance
        {
            get
            {
                if (instance == null) instance = Resources.Load<GameWindowsLibrary>("GameWindows");
                return instance;
            }
        }
    }
}
